(async()=>{const container=document.getElementById('reviews-list');const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));try{const response=await fetch('/api/reviews');if(!response.ok)throw Error();const {reviews}=await response.json();container.innerHTML=reviews.length?reviews.map(r=>`<article class="review-card"><p aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}</p><p style="white-space:pre-wrap">${escape(r.message)}</p><strong>${escape(r.name)}</strong><p>Completed GoRide rental · ${escape(new Date(r.createdAt).toLocaleDateString())}</p></article>`).join(''):'<p>Reviews will appear here after completed rides and owner approval.</p>';}catch{container.textContent='Reviews are temporarily unavailable.';}})();
